  if (!m || !m[2]) return new Response("Not found", { status: 404 });
  const acc = req.headers.get("accept") || "", fmt = env && env.IMGX === "1" ? (/image\/avif/.test(acc) ? "avif" : /image\/webp/.test(acc) ? "webp" : "") : "";
